const pptxgen = require('pptxgenjs');

const path = require('path');

// Slide size for LAYOUT_16x9 is 10 x 5.625 inches
const SLIDE_W = 10;
const SLIDE_H = 5.625;

// Theme (research-forward, high contrast)
const COLORS = {
  bgDark: '0B1220',
  bgLight: 'F7F8FB',
  ink: '0F172A',
  inkMuted: '475569',
  border: 'D6DBE8',
  card: 'FFFFFF',
  accent: '22C55E', // green
  accent2: '38BDF8', // sky
  accent3: 'A78BFA', // violet
  warn: 'F59E0B',
  reject: 'EF4444',
};

const FONTS = {
  head: 'Cambria',
  body: 'Calibri',
  mono: 'Consolas',
};

function addTopBar(slide, { title, variant = 'light', rightTag } = {}) {
  if (variant === 'dark') {
    slide.addShape(ShapeType.rect, {
      x: 0,
      y: 0,
      w: SLIDE_W,
      h: 0.78,
      fill: { color: COLORS.bgDark },
      line: { color: COLORS.bgDark },
    });
    slide.addText(title || '', {
      x: 0.6,
      y: 0.18,
      w: 8.6,
      h: 0.45,
      fontFace: FONTS.head,
      fontSize: 26,
      bold: true,
      color: 'FFFFFF',
      margin: 0,
    });
    if (rightTag) {
      slide.addShape(ShapeType.roundRect, {
        x: 8.2,
        y: 0.19,
        w: 1.6,
        h: 0.42,
        fill: { color: COLORS.accent2, transparency: 15 },
        line: { color: COLORS.accent2 },
        radius: 0.18,
      });
      slide.addText(rightTag, {
        x: 8.2,
        y: 0.21,
        w: 1.6,
        h: 0.38,
        fontFace: FONTS.body,
        fontSize: 12,
        bold: true,
        color: 'FFFFFF',
        align: 'center',
        valign: 'middle',
        margin: 0,
      });
    }
    return;
  }

  slide.addShape(ShapeType.rect, {
    x: 0,
    y: 0,
    w: SLIDE_W,
    h: 0.7,
    fill: { color: COLORS.bgLight },
    line: { color: COLORS.bgLight },
  });
  slide.addText(title || '', {
    x: 0.6,
    y: 0.16,
    w: 8.7,
    h: 0.45,
    fontFace: FONTS.head,
    fontSize: 26,
    bold: true,
    color: COLORS.ink,
    margin: 0,
  });
  if (rightTag) {
    slide.addShape(ShapeType.roundRect, {
      x: 8.2,
      y: 0.16,
      w: 1.6,
      h: 0.42,
      fill: { color: COLORS.bgDark },
      line: { color: COLORS.bgDark },
      radius: 0.18,
    });
    slide.addText(rightTag, {
      x: 8.2,
      y: 0.18,
      w: 1.6,
      h: 0.38,
      fontFace: FONTS.body,
      fontSize: 12,
      bold: true,
      color: 'FFFFFF',
      align: 'center',
      valign: 'middle',
      margin: 0,
    });
  }

