function addTable(slide, { x, y, colWs, rowH, header, rows } = {}) {
  // header and rows are arrays of strings
  const tableRows = [];
  tableRows.push(header);
  rows.forEach((r) => tableRows.push(r));
  slide.addTable(tableRows, {
    x,
    y,
    w: colWs.reduce((a, b) => a + b, 0),
    colW: colWs,
    rowH,
    fontFace: FONTS.body,
    fontSize: 11,
    color: COLORS.ink,
    border: { type: 'solid', color: COLORS.border, pt: 1 },
    fill: 'FFFFFF',
    valign: 'middle',
    autoFit: false,
    rowFill: ['F8FAFC'],
  });

  // style header row
  addShape(pptx, slide, 'rect', {
    x,
    y,
    w: colWs.reduce((a, b) => a + b, 0),
    h: rowH,
    fill: { color: COLORS.bgDark },
    line: { color: COLORS.bgDark },
    transparency: 15,
  });
  slide.addTable([header], {
    x,
    y,
    w: colWs.reduce((a, b) => a + b, 0),
    colW: colWs,
    rowH,
    fontFace: FONTS.body,
    fontSize: 11,
    bold: true,
    color: 'FFFFFF',
    border: { type: 'solid', color: COLORS.bgDark, pt: 1 },
    fill: COLORS.bgDark,
    valign: 'middle',
    autoFit: false,
  });
}

